head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00206.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

// WebSquare 컴포넌트 이벤트 함수
scwin.dts_Div1_OnLoadError = function() {
    $c.win.alert(dts_Div1);
};

scwin.dts_Div1_OnLoadCompleted = function(rowcount) {
    if (dts_Div1.errorMsg) {
        alert(dts_Div1.errorMsg);
    }
};

scwin.dts_Excel_OnLoadCompleted = function(rowcount) {
    $c.data.downloadGridViewExcel(grd_Excel, "배당", "", "1");
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    grd_Excel.hide();
    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dts_Div1.removeAll();
    dts_Div2.removeAll();
    dts_Div3.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    //필수항목 체크.

    //----W-Craft WebSquare 변환 확인: fn_GetKisCd----//
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    //----W-Craft WebSquare 변환 확인: fn_GetAcntclsDt----//
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * 배당 조회
 */
scwin.search = function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }
    scwin.search1(); // 상단 그리드 조회
    scwin.search2(); // 중단 그리드 조회
    scwin.search3(); // 하단 그리드 조회

};

/**
 * 상단 조회
 */
scwin.search1 = function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_Div1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Div1=body.content",
        submitDoneHandler : scwin.sbm_dts_Div1_submitdone, // TODO Stage2: submitdone 핸들러 미정의 (정적 submission 노드 부재; 후보: scwin.dts_Div1_OnLoadCompleted)
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

/**
 * 중단 조회
 */
scwin.search2 = function() {
    const sbmOptions = {
        id : "sbm_dts_Div2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Div2=body.content",
        submitDoneHandler : scwin.sbm_dts_Div2_submitdone, // TODO Stage2: submitdone 핸들러 미정의
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

/**
 * 하단 조회
 */
scwin.search3 = function() {
    const sbmOptions = {
        id : "sbm_dts_Div3",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Div3=body.content",
        submitDoneHandler : scwin.sbm_dts_Div3_submitdone, // TODO Stage2: submitdone 핸들러 미정의
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

/**
 * 엑셀용 데이터 조회
 */
scwin.searchExcel = function() {
    dts_Excel.removeAll();
    /*
		var url = "/listingCommon.do?SCREN_ID=" +vScrenID
                + "&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
                + "&method=listGeneralForDynamic"
                + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp"
                + "&queryId=krx.lds.stf.fis.select.div4"
				+ "&outputMessageId=FIS_DIV2"
				+ fn_GetParam();

		const sbmOptions = {
		    id : "sbm_dts_Excel",
		    action : "/listingCommon.do",
		    ref : "",
		    target : "dts_Excel=body.content",
		    submitDoneHandler : scwin.sbm_dts_Excel_submitdone,
		    isProcessMsg : false
		};

		$c.sbm.executeDynamic(sbmOptions);


		*/

    // 데이터셋을 복사하는 방식으로 하자.
    $c.stf.copyDataSetHeader(dts_Div2, dts_Excel);

    // dts_Div2 Copy
    scwin.appendDataset(dts_Excel, dts_Div1);
    scwin.appendDataset(dts_Excel, dts_Div2);
    scwin.appendDataset(dts_Excel, dts_Div3);
    $c.data.downloadGridViewExcel(grd_Excel, "배당", "", "1");
};

/**
 * 데이터셋 append
 */
scwin.appendDataset = function(pDsExcel, pDsTar) {
    // TODO Stage2: 0-based 검토 (nRow 1-based 루프 + getCellData 인덱스 유지)
    for (let nRow = 1; nRow <= pDsTar.getRowCount(); nRow++) {
        const nIdx = pDsExcel.addRow(); // TODO Stage2: Gauce AddRow+RowPosition → addRow 반환 인덱스 (0-based 검토)
        pDsExcel.setCellData(nIdx, "DIV_TYP", pDsTar.getCellData(nRow, "DIV_TYP"));
        pDsExcel.setCellData(nIdx, "GUBUN", pDsTar.getCellData(nRow, "GUBUN"));
        pDsExcel.setCellData(nIdx, "DIV1", pDsTar.getCellData(nRow, "DIV1"));
        pDsExcel.setCellData(nIdx, "DIV_RT1", pDsTar.getCellData(nRow, "DIV_RT1"));
        pDsExcel.setCellData(nIdx, "DIV2", pDsTar.getCellData(nRow, "DIV2"));
        pDsExcel.setCellData(nIdx, "DIV_RT2", pDsTar.getCellData(nRow, "DIV_RT2"));
        pDsExcel.setCellData(nIdx, "DIV3", pDsTar.getCellData(nRow, "DIV3"));
        pDsExcel.setCellData(nIdx, "DIV_RT3", pDsTar.getCellData(nRow, "DIV_RT3"));
        pDsExcel.setCellData(nIdx, "DIV4", pDsTar.getCellData(nRow, "DIV4"));
        pDsExcel.setCellData(nIdx, "DIV_RT4", pDsTar.getCellData(nRow, "DIV_RT4"));
        pDsExcel.setCellData(nIdx, "DIV5", pDsTar.getCellData(nRow, "DIV5"));
        pDsExcel.setCellData(nIdx, "DIV_RT5", pDsTar.getCellData(nRow, "DIV_RT5"));
    }
};

/**
 * 파라미터 스트링 만들기
 */
scwin.getParam = function() {
    let vParam = "";
    vParam = "&param01=" + scwin.vKisCd + "&param02=" + scwin.vArray[0].VALUE + "&param03=" + scwin.vArray[1].VALUE + "&param04=" + scwin.vArray[2].VALUE + "&param05=" + scwin.vArray[3].VALUE + "&param06=" + scwin.vArray[4].VALUE;
    return vParam;
};

/**
 * 그리드 헤더의 제목을 세팅.
 */
scwin.setGrdHeaderNm = function(pArray) {
    $c.cm.setColumnProp(grd_Div1, "DIV1", "Name", pArray[0].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV2", "Name", pArray[1].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV3", "Name", pArray[2].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV4", "Name", pArray[3].TEXT);
    $c.cm.setColumnProp(grd_Div1, "DIV5", "Name", pArray[4].TEXT);

    // 엑셀 다운용
    $c.cm.setColumnProp(grd_Excel, "DIV1", "Name", pArray[0].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV2", "Name", pArray[1].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV3", "Name", pArray[2].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV4", "Name", pArray[3].TEXT);
    $c.cm.setColumnProp(grd_Excel, "DIV5", "Name", pArray[4].TEXT);
    scwin.vArray = pArray;
};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {
    if (dts_Div1.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    // 엑셀용 데이터 조회를 위해 쿼리 날림.
    scwin.searchExcel();
};

scwin.gform_onload = function() {
    scwin.init();
};
